CREATE TABLE users (id uuid PRIMARY KEY, auth_issuer text NOT NULL, auth_subject text NOT NULL, display_name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), UNIQUE(auth_issuer,auth_subject));
CREATE TABLE courses (id uuid PRIMARY KEY, title text NOT NULL, created_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE classes (id uuid PRIMARY KEY, course_id uuid NOT NULL REFERENCES courses(id), title text NOT NULL, term text NOT NULL, timezone text NOT NULL, archived_at timestamptz);
CREATE TABLE enrollments (id uuid PRIMARY KEY, class_id uuid NOT NULL REFERENCES classes(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('student','teacher','assistant')), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), UNIQUE(class_id,user_id), UNIQUE(id,class_id));
CREATE TABLE assignments (id uuid PRIMARY KEY, class_id uuid NOT NULL REFERENCES classes(id), title text NOT NULL, instructions text NOT NULL, module text NOT NULL, due_at timestamptz NOT NULL, late_until timestamptz, max_score numeric NOT NULL CHECK(max_score>0), status text NOT NULL CHECK(status IN ('draft','published','closed')), allow_resubmission boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 0 CHECK(revision>=0), UNIQUE(id,class_id), CHECK(late_until IS NULL OR late_until>=due_at));
CREATE TABLE submissions (id uuid PRIMARY KEY, assignment_id uuid NOT NULL, class_id uuid NOT NULL, enrollment_id uuid NOT NULL, state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','submitted','graded','returned')), draft jsonb NOT NULL, current_version_id uuid, revision integer NOT NULL DEFAULT 0 CHECK(revision>=0), UNIQUE(assignment_id,enrollment_id), UNIQUE(id,class_id), FOREIGN KEY(assignment_id,class_id) REFERENCES assignments(id,class_id), FOREIGN KEY(enrollment_id,class_id) REFERENCES enrollments(id,class_id));
CREATE TABLE assets (id uuid PRIMARY KEY, owner_user_id uuid NOT NULL REFERENCES users(id), sha256 char(64) NOT NULL, mime_type text NOT NULL, byte_size bigint NOT NULL CHECK(byte_size>0 AND byte_size<=20971520), width integer NOT NULL, height integer NOT NULL, storage_key text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('pending','ready','quarantined')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE submission_versions (id uuid PRIMARY KEY, submission_id uuid NOT NULL REFERENCES submissions(id), version_no integer NOT NULL CHECK(version_no>0), description text NOT NULL, color_tags jsonb NOT NULL, submitted_at timestamptz NOT NULL, due_at_snapshot timestamptz NOT NULL, is_late boolean NOT NULL, content_hash char(64) NOT NULL, UNIQUE(submission_id,version_no), UNIQUE(id,submission_id));
ALTER TABLE submissions ADD CONSTRAINT current_version_belongs_to_submission FOREIGN KEY(current_version_id,id) REFERENCES submission_versions(id,submission_id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE submission_version_assets (version_id uuid NOT NULL REFERENCES submission_versions(id), asset_id uuid NOT NULL REFERENCES assets(id), role text NOT NULL CHECK(role IN ('final','process')), ordinal integer NOT NULL CHECK(ordinal BETWEEN 0 AND 2), sha256 char(64) NOT NULL, PRIMARY KEY(version_id,asset_id,role), UNIQUE(version_id,ordinal));
CREATE TABLE planets (id uuid PRIMARY KEY, owner_enrollment_id uuid NOT NULL UNIQUE REFERENCES enrollments(id));
CREATE TABLE archive_entries (id uuid PRIMARY KEY, planet_id uuid NOT NULL REFERENCES planets(id), submission_version_id uuid NOT NULL REFERENCES submission_versions(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(planet_id,submission_version_id));
CREATE TABLE reviews (id uuid PRIMARY KEY, submission_version_id uuid NOT NULL REFERENCES submission_versions(id), reviewer_enrollment_id uuid NOT NULL REFERENCES enrollments(id), decision text NOT NULL CHECK(decision IN ('graded','returned')), score numeric CHECK(score>=0), comment text NOT NULL, supersedes_id uuid REFERENCES reviews(id), created_at timestamptz NOT NULL, CHECK((decision='graded' AND score IS NOT NULL) OR (decision='returned' AND score IS NULL)));
CREATE TABLE idempotency_records (actor_id uuid NOT NULL REFERENCES users(id), operation text NOT NULL, key text NOT NULL, request_hash char(64) NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,operation,key));
CREATE TABLE sessions (token_hash char(64) PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf_token text NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX submissions_assignment_state ON submissions(assignment_id,state);
CREATE INDEX enrollments_user_active ON enrollments(user_id,status);
CREATE INDEX assignments_class_due ON assignments(class_id,due_at);
CREATE INDEX versions_submission_order ON submission_versions(submission_id,version_no DESC);
CREATE INDEX version_assets_asset ON submission_version_assets(asset_id);
CREATE UNIQUE INDEX one_review_successor ON reviews(supersedes_id) WHERE supersedes_id IS NOT NULL;
CREATE FUNCTION immutable_course_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable course history cannot be updated or deleted'; END $$;
CREATE TRIGGER freeze_versions BEFORE UPDATE OR DELETE ON submission_versions FOR EACH ROW EXECUTE FUNCTION immutable_course_history();
CREATE TRIGGER freeze_version_assets BEFORE UPDATE OR DELETE ON submission_version_assets FOR EACH ROW EXECUTE FUNCTION immutable_course_history();
CREATE TRIGGER freeze_reviews BEFORE UPDATE OR DELETE ON reviews FOR EACH ROW EXECUTE FUNCTION immutable_course_history();
CREATE FUNCTION student_submission_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM enrollments WHERE id=NEW.enrollment_id AND class_id=NEW.class_id AND role='student') THEN RAISE EXCEPTION 'Submission requires a student enrollment'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_student_submission BEFORE INSERT OR UPDATE OF enrollment_id,class_id ON submissions FOR EACH ROW EXECUTE FUNCTION student_submission_only();
CREATE FUNCTION immutable_original_asset() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.owner_user_id<>OLD.owner_user_id OR NEW.sha256<>OLD.sha256 OR NEW.mime_type<>OLD.mime_type OR NEW.byte_size<>OLD.byte_size OR NEW.width<>OLD.width OR NEW.height<>OLD.height OR NEW.storage_key<>OLD.storage_key THEN RAISE EXCEPTION 'Original asset is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER freeze_original_asset BEFORE UPDATE ON assets FOR EACH ROW EXECUTE FUNCTION immutable_original_asset();
